// Statusaenderungen erkennen, indem der aktuelle Stand mit dem letzten
// verglichen wird. Der letzte Stand liegt in n8n's eigenem Speicher, der
// zwischen Durchlaeufen erhalten bleibt.
const statisch = $getWorkflowStaticData('global');
statisch.letzterStand = statisch.letzterStand || {};
const ersterLauf = Object.keys(statisch.letzterStand).length === 0;

const roh = $json.data ?? $json;
const tickets = (roh && typeof roh === 'object') ? roh : {};

const SPALTEN = {
  triage: 'Triage',
  todo: 'To do',
  'in-progress': 'In progress',
  'await-feedback': 'Await feedback',
  done: 'Done',
};

const aenderungen = [];
for (const [schluessel, t] of Object.entries(tickets)) {
  if (!t || typeof t !== 'object') continue;
  const vorher = statisch.letzterStand[schluessel];
  const jetzt = String(t.status || '');

  // Beim allerersten Lauf gibt es keinen Vergleichswert. Dann nur den Stand
  // merken und NICHTS verschicken - sonst bekaeme jeder Ersteller sofort eine
  // Mail fuer ein Ticket, das sich gar nicht bewegt hat.
  if (!ersterLauf && vorher && vorher !== jetzt) {
    const ersteller = t.creator || {};
    if (ersteller.email) {
      aenderungen.push({ json: {
        an: ersteller.email,
        titel: t.title || 'Ticket ohne Titel',
        vonSpalte: SPALTEN[vorher] || vorher,
        nachSpalte: SPALTEN[jetzt] || jetzt,
        istExtern: ersteller.type === 'extern',
      }});
    }
  }
  statisch.letzterStand[schluessel] = jetzt;
}

// Geloeschte Tickets aus dem gemerkten Stand entfernen, damit er nicht waechst
for (const schluessel of Object.keys(statisch.letzterStand)) {
  if (!(schluessel in tickets)) delete statisch.letzterStand[schluessel];
}

return aenderungen;

// Benachrichtigungstext bauen.
const eigenesPostfach = String($env.JOIN_MAIL_USER || '').toLowerCase();
const ergebnisse = [];
for (const item of items) {
  const j = item.json;
  const an = String(j.an || '').toLowerCase();
  // Schutz vor Endlosschleife: nie an das eigene Postfach schreiben
  if (!an || an === eigenesPostfach) continue;

  ergebnisse.push({ json: {
    an,
    betreff: `Ihr Ticket wurde verschoben: ${j.titel}`,
    text: [
      'Hallo,',
      '',
      'es gibt Bewegung bei Ihrem Ticket:',
      '',
      `  ${j.titel}`,
      `  ${j.vonSpalte}  ->  ${j.nachSpalte}`,
      '',
      j.nachSpalte === 'Done'
        ? 'Das Ticket ist damit abgeschlossen. Vielen Dank fuer Ihre Anfrage!'
        : 'Wir halten Sie auf dem Laufenden.',
      '',
      'Hinweis: Diese Nachricht wurde automatisch erzeugt.',
    ].join('\n')
  }});
}
return ergebnisse;
